1	/**
2	 * LanChat 前端交互逻辑。
3	 *
4	 * 全局状态:
5	 *   myInfo       - 本机信息 {uuid, name, ip, network, ws_port}
6	 *   onlinePeers  - 在线节点 Map<uuid, {name, ip}>
7	 *   contacts     - 历史联系人 Map<uuid, {name, ip, status, messages[]}>
8	 *   pendingReqs  - 待处理连接请求 Map<uuid, {name}>
9	 *   activeChats  - 活跃聊天 WS Map<uuid, WebSocket>
10	 *   currentChat  - 当前显示的聊天 uuid | null
11	 *   pendingMsgs  - 待确认消息 Map<msg_id, {content, uuid, timestamp}>
12	 */
13	
14	// ===== 全局状态 =====
15	let myInfo = null;
16	let onlinePeers = new Map();
17	let contacts = new Map();
18	let pendingRequests = new Map();
19	let activeChats = new Map();
20	let currentChat = null;
21	let pendingMessages = new Map();
22	let controlWs = null;
23	let reconnectTimer = null;
24	let reconnectAttempts = 0;
25	
26	// ===== DOM 引用 =====
27	const $ = (id) => document.getElementById(id);
28	const onlineList = $('online-list');
29	const onlineCount = $('online-count');
30	const pendingList = $('pending-list');
31	const pendingCount = $('pending-count');
32	const panelPending = $('panel-pending');
33	const contactsList = $('contacts-list');
34	const contactsCount = $('contacts-count');
35	const chatPlaceholder = $('chat-placeholder');
36	const chatContainer = $('chat-container');
37	const chatPeerName = $('chat-peer-name');
38	const chatPeerStatus = $('chat-peer-status');
39	const chatMessages = $('chat-messages');
40	const msgInput = $('msg-input');
41	const btnSend = $('btn-send');
42	const btnSendFile = $('btn-send-file');
43	const fileInput = $('file-input');
44	const btnCloseChat = $('btn-close-chat');
45	const btnDeleteContact = $('btn-delete-contact');
46	const btnScan = $('btn-scan');
47	const btnEditName = $('btn-edit-name');
48	const modalOverlay = $('modal-overlay');
49	const modalNameInput = $('modal-name-input');
50	const fileModalOverlay = $('file-modal-overlay');
51	const fileModalTitle = $('file-modal-title');
52	const fileModalBody = $('file-modal-body');
53	const fileModalButtons = $('file-modal-buttons');
54	
55	// ===== 初始化 =====
56	async function init() {
57	    await connectControl();
58	    bindEvents();
59	    startPolling();
60	}
61	
62	/** 连接控制 WebSocket */
63	async function connectControl() {
64	    const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
65	    const url = `${protocol}//${location.host}/ws/control`;
66	
67	    return new Promise((resolve) => {
68	        controlWs = new WebSocket(url);
69	
70	        controlWs.onopen = () => {
71	            reconnectAttempts = 0;
72	            console.log('[Control] 已连接');
73	        };
74	
75	        controlWs.onmessage = (e) => {
76	            const msg = JSON.parse(e.data);
77	            handleControlMessage(msg);
78	            if (msg.type === 'init') resolve();
79	        };
80	
81	        controlWs.onclose = () => {
82	            console.log('[Control] 断开，尝试重连...');
83	            scheduleReconnect();
84	        };
85	
86	        controlWs.onerror = () => {};
87	    });
88	}
89	
90	/** 控制 WS 断开后指数退避重连 */
91	function scheduleReconnect() {
92	    if (reconnectTimer) return;
93	    const delay = Math.min(1000 * Math.pow(2, reconnectAttempts), 30000);
94	    const jitter = delay * (0.8 + Math.random() * 0.4);
95	    reconnectAttempts++;
96	    reconnectTimer = setTimeout(async () => {
97	        reconnectTimer = null;
98	        await connectControl();
99	    }, jitter);
100	}
101	
102	// ===== 事件绑定 =====
103	function bindEvents() {
104	    btnScan.addEventListener('click', () => fetchPeers());
105	    btnEditName.addEventListener('click', showEditNameModal);
106	    $('btn-modal-cancel').addEventListener('click', hideEditNameModal);
107	    $('btn-modal-save').addEventListener('click', saveName);
108	    modalNameInput.addEventListener('keydown', (e) => {
109	        if (e.key === 'Enter') saveName();
110	    });
111	    btnSend.addEventListener('click', sendCurrentMessage);
112	    msgInput.addEventListener('keydown', (e) => {
113	        if (e.key === 'Enter') sendCurrentMessage();
114	    });
115	    btnSendFile.addEventListener('click', () => fileInput.click());
116	    fileInput.addEventListener('change', onFileSelected);
117	    btnCloseChat.addEventListener('click', closeCurrentChat);
118	    btnDeleteContact.addEventListener('click', deleteCurrentContact);
119	}
120	
121	// ===== 定时轮询 =====
122	function startPolling() {
123	    setInterval(fetchPeers, 3000);
124	    setInterval(fetchContacts, 5000);
125	    fetchPeers();
126	    fetchContacts();
127	}
128	
129	async function fetchPeers() {
130	    try {
131	        const resp = await fetch('/api/peers');
132	        const peers = await resp.json();
133	        updateOnlinePeers(peers);
134	    } catch (e) { /* ignore */ }
135	}
136	
137	async function fetchContacts() {
138	    try {
139	        const resp = await fetch('/api/contacts');
140	        const list = await resp.json();
141	        updateContacts(list);
142	    } catch (e) { /* ignore */ }
143	}
144	
145	// ===== 控制消息处理 =====
146	function handleControlMessage(msg) {
147	    const handlers = {
148	        init: handleInit,
149	        peer_online: handlePeerOnline,
150	        peer_offline: handlePeerOffline,
151	        incoming_connection: handleIncomingConnection,
152	        pending_update: handlePendingUpdate,
153	        connection_established: handleConnectionEstablished,
154	        peer_disconnected: handlePeerDisconnected,
155	        chat_message: handleIncomingMessage,
156	        message_ack: handleMessageAck,
157	        send_failed: handleSendFailed,
158	        incoming_file_request: handleIncomingFileRequest,
159	        file_request_response: handleFileRequestResponse,
160	        transfer_progress: handleTransferProgress,
161	        transfer_complete: handleTransferComplete,
162	        transfer_cancelled: handleTransferCancelled,
163	    };
164	    const handler = handlers[msg.type];
165	    if (handler) handler(msg);
166	}
167	
168	function handleInit(msg) {
169	    myInfo = msg;
170	    $('my-name-label').textContent = msg.name;
171	    $('my-ip-label').textContent = `IP: ${msg.ip}`;
172	    $('my-network-label').textContent = `网段: ${msg.network}`;
173	    // msg.token 是自己的 token，建立连接时需出示给对方后端验证
174	
175	    // 步骤1：先用 init 消息中的在线节点填充 onlinePeers（不等轮询）
176	    if (msg.online_peers && msg.online_peers.length > 0) {
177	        updateOnlinePeers(msg.online_peers);
178	    }
179	
180	    // 步骤2：加载历史联系人（此时 onlinePeers 已有数据，渲染时状态正确）
181	    if (msg.contacts && msg.contacts.length > 0) {
182	        updateContacts(msg.contacts);
183	    }
184	}
185	
186	function handlePeerOnline(msg) {
187	    onlinePeers.set(msg.uuid, { name: msg.name, ip: msg.ip, ws_port: msg.ws_port, token: msg.token });
188	    // 如果历史联系人里有，更新在线状态
189	    if (contacts.has(msg.uuid)) {
190	        contacts.get(msg.uuid).status = 'online';
191	    }
192	    renderOnlineList();
193	    renderContactsList();
194	    updateChatHeaderStatus();
195	}
196	
197	function handlePeerOffline(msg) {
198	    onlinePeers.delete(msg.uuid);
199	    if (contacts.has(msg.uuid)) {
200	        contacts.get(msg.uuid).status = 'offline';
201	    }
202	    // 对应聊天 WS 断开
203	    const ws = activeChats.get(msg.uuid);
204	    if (ws) {
205	        ws.close();
206	        activeChats.delete(msg.uuid);
207	    }
208	    renderOnlineList();
209	    renderContactsList();
210	    updateChatHeaderStatus();
211	    addSystemMessage(msg.uuid, `${msg.name} 已下线`);
212	}
213	
214	function handleIncomingConnection(msg) {
215	    // 保存连接请求信息，包括 IP 和端口，以便同意后反向建立连接
216	    pendingRequests.set(msg.uuid, { name: msg.name, ip: msg.ip, ws_port: msg.ws_port });
217	    renderPendingList();
218	}
219	
220	function handlePendingUpdate(msg) {
221	    // county 可能在 pending 列表被其他地方修改后推送
222	    if (msg.count === 0) pendingRequests.clear();
223	}
224	
225	function handleConnectionEstablished(msg) {
226	    pendingRequests.delete(msg.uuid);
227	    // 加入联系人
228	    contacts.set(msg.uuid, {
229	        name: msg.name,
230	        ip: msg.ip,
231	        status: 'online',
232	        messages: [],
233	    });
234	    renderPendingList();
235	    renderContactsList();
236	    // 如果正在等对方的确认（主动发起方），打开聊天
237	    if (currentChat === msg.uuid || !currentChat) {
238	        openChat(msg.uuid);
239	    }
240	}
241	
242	function handlePeerDisconnected(msg) {
243	    activeChats.delete(msg.uuid);
244	    pendingRequests.delete(msg.uuid);
245	    renderPendingList();
246	    if (currentChat === msg.uuid) {
247	        updateChatHeaderStatus();
248	        addSystemMessage(msg.uuid, `${msg.name || '对方'} 已断开连接`);
249	    }
250	}
251	
252	function handleIncomingMessage(msg) {
253	    const uuid = msg.from;
254	    // 保存消息到联系人
255	    if (!contacts.has(uuid)) {
256	        contacts.set(uuid, { name: msg.from_name, ip: '', status: 'online', messages: [] });
257	    }
258	    const contact = contacts.get(uuid);
259	    contact.messages.push({
260	        from: uuid,
261	        content: msg.content,
262	        msg_id: msg.msg_id,
263	        timestamp: msg.timestamp,
264	    });
265	    if (currentChat === uuid) {
266	        renderMessages(uuid);
267	    }
268	    // 当前没有聊天窗口时，自动打开
269	    if (!currentChat) {
270	        openChat(uuid);
271	    }
272	    renderContactsList();
273	}
274	
275	function handleMessageAck(msg) {
276	    pendingMessages.delete(msg.msg_id);
277	    if (currentChat) renderMessages(currentChat);
278	}
279	
280	function handleSendFailed(msg) {
281	    // 标记消息发送失败
282	    const pending = pendingMessages.get(msg.msg_id);
283	    if (pending) {
284	        pending.status = 'failed';
285	        pendingMessages.set(msg.msg_id, pending);
286	    }
287	    if (currentChat) renderMessages(currentChat);
288	}
289	
290	// ===== 文件传输消息处理 =====
291	
292	function handleIncomingFileRequest(msg) {
293	    showFileRequestModal(msg);
294	}
295	
296	function handleFileRequestResponse(msg) {
297	    if (msg.accepted) {
298	        console.log(`[Transfer] 对方接受传输: ${msg.transfer_id}`);
299	    } else {
300	        showToast('对方拒绝了文件传输');
301	    }
302	}
303	
304	function handleTransferProgress(msg) {
305	    // 更新传输进度（可在聊天区或侧边栏展示进度条）
306	    console.log(`[Transfer] 进度: ${msg.received_bytes}/${msg.total_bytes}`);
307	}
308	
309	function handleTransferComplete(msg) {
310	    showToast(`文件接收完成: ${msg.file_name}`);
311	    addSystemMessage(currentChat, `文件 ${msg.file_name} 接收完成 ✓`);
312	}
313	
314	function handleTransferCancelled(msg) {
315	    showToast('对方取消了文件传输');
316	    addSystemMessage(currentChat, '文件传输已取消');
317	}
318	
319	// ===== 在线列表渲染 =====
320	function updateOnlinePeers(peers) {
321	    onlinePeers.clear();
322	    for (const p of peers) {
323	        // 保存 token，用于建立连接时出示给对方后端验证
324	        onlinePeers.set(p.uuid, { name: p.name, ip: p.ip, ws_port: p.ws_port, token: p.token });
325	    }
326	    renderOnlineList();
327	    // 同时刷新联系人列表的状态（在线/离线圆点）
328	    renderContactsList();
329	    updateChatHeaderStatus();
330	}
331	
332	function renderOnlineList() {
333	    onlineCount.textContent = onlinePeers.size;
334	    if (onlinePeers.size === 0) {
335	        onlineList.innerHTML = '<div class="empty-hint">暂无在线用户</div>';
336	        return;
337	    }
338	    onlineList.innerHTML = '';
339	    for (const [uuid, peer] of onlinePeers) {
340	        const div = document.createElement('div');
341	        div.className = `item${currentChat === uuid ? ' active' : ''}`;
342	        div.innerHTML = `
343	            <span class="dot online"></span>
344	            <div class="info">
345	                <div class="name">${esc(peer.name)}</div>
346	                <div class="sub">${esc(peer.ip)}</div>
347	            </div>`;
348	        div.addEventListener('click', () => connectToPeer(uuid, peer.name, peer.ip));
349	        onlineList.appendChild(div);
350	    }
351	}
352	
353	// ===== 待处理请求列表渲染 =====
354	function renderPendingList() {
355	    if (pendingRequests.size === 0) {
356	        panelPending.style.display = 'none';
357	        return;
358	    }
359	    panelPending.style.display = '';
360	    pendingCount.textContent = pendingRequests.size;
361	    pendingList.innerHTML = '';
362	    for (const [uuid, req] of pendingRequests) {
363	        const div = document.createElement('div');
364	        div.className = 'item';
365	        div.innerHTML = `
366	            <span class="dot pending"></span>
367	            <div class="info"><div class="name">${esc(req.name)}</div></div>
368	            <div class="actions">
369	                <button class="btn-accept" data-uuid="${uuid}">同意</button>
370	                <button class="btn-reject" data-uuid="${uuid}">拒绝</button>
371	            </div>`;
372	        div.querySelector('.btn-accept').addEventListener('click', (e) => {
373	            e.stopPropagation();
374	            respondConnection(uuid, true);
375	        });
376	        div.querySelector('.btn-reject').addEventListener('click', (e) => {
377	            e.stopPropagation();
378	            respondConnection(uuid, false);
379	        });
380	        pendingList.appendChild(div);
381	    }
382	}
383	
384	async function respondConnection(uuid, accepted) {
385	    controlWs.send(JSON.stringify({
386	        type: 'connection_response',
387	        to_uuid: uuid,
388	        accepted: accepted,
389	    }));
390	    pendingRequests.delete(uuid);
391	    renderPendingList();
392	    if (accepted) {
393	        // 保存联系人信息并打开聊天窗口
394	        // 注意：消息发送走 A→B后端的 chat WS（双向），B→A 走 B后端的 active_chats[A] 回传同一 WS
395	        const peer = onlinePeers.get(uuid) || { name: 'Unknown', ip: '' };
396	        contacts.set(uuid, { name: peer.name, ip: peer.ip, status: 'online', messages: [] });
397	        openChat(uuid);
398	    }
399	}
400	
401	// ===== 历史联系人列表渲染 =====
402	function updateContacts(list) {
403	    for (const c of list) {
404	        if (!contacts.has(c.uuid)) {
405	            contacts.set(c.uuid, {
406	                name: c.name,
407	                ip: c.ip,
408	                status: c.status,
409	                messages: [],
410	            });
411	        } else {
412	            contacts.get(c.uuid).status = c.status;
413	            contacts.get(c.uuid).name = c.name || contacts.get(c.uuid).name;
414	            contacts.get(c.uuid).ip = c.ip || contacts.get(c.uuid).ip;
415	        }
416	    }
417	    renderContactsList();
418	    updateChatHeaderStatus();
419	}
420	
421	function renderContactsList() {
422	    const list = Array.from(contacts.entries())
423	        .sort((a, b) => {
424	            // 在线排前面，同状态按名字排序
425	            if (a[1].status !== b[1].status) return a[1].status === 'online' ? -1 : 1;
426	            return a[1].name.localeCompare(b[1].name);
427	        });
428	
429	    contactsCount.textContent = list.length;
430	    if (list.length === 0) {
431	        contactsList.innerHTML = '<div class="empty-hint">暂无历史联系人</div>';
432	        return;
433	    }
434	
435	    contactsList.innerHTML = '';
436	    for (const [uuid, contact] of list) {
437	        const div = document.createElement('div');
438	        div.className = `item${currentChat === uuid ? ' active' : ''}`;
439	        // 用实时在线列表判断状态，与点击行为保持一致
440	        const isOnline = onlinePeers.has(uuid);
441	        const dotClass = isOnline ? 'online' : 'offline';
442	        const statusText = isOnline ? '' : ' (离线)';
443	        div.innerHTML = `
444	            <span class="dot ${dotClass}"></span>
445	            <div class="info">
446	                <div class="name">${esc(contact.name)}${statusText}</div>
447	                <div class="sub">${esc(contact.ip)}</div>
448	            </div>`;
449	        div.addEventListener('click', () => {
450	            // 用实时在线列表判断（与 updateChatHeaderStatus 数据源一致）
451	            if (onlinePeers.has(uuid)) {
452	                // 在线 → 自动发送连接请求
453	                connectToPeer(uuid, contact.name, contact.ip);
454	            } else {
455	                // 离线 → 提示用户，但仍然加载历史聊天记录
456	                showToast('对方不在线');
457	                openChat(uuid);
458	            }
459	        });
460	        // 右键删除
461	        div.addEventListener('contextmenu', (e) => {
462	            e.preventDefault();
463	            if (confirm(`确定删除联系人 ${contact.name} 及聊天记录？`)) {
464	                deleteContact(uuid);
465	            }
466	        });
467	        contactsList.appendChild(div);
468	    }
469	}
470	
471	async function deleteContact(uuid) {
472	    try {
473	        await fetch(`/api/contacts/${uuid}`, { method: 'DELETE' });
474	    } catch (e) { /* ignore */ }
475	    contacts.delete(uuid);
476	    if (currentChat === uuid) closeCurrentChat();
477	    renderContactsList();
478	}
479	
480	// ===== 连接对端 / 打开聊天 =====
481	
482	/**
483	 * 主动发起与对端的 WebSocket 连接。
484	 * 流程: 连接 ws://peer_ip:ws_port/ws/chat → 发 connect_request（带 token）→ 等 connect_accepted
485	 */
486	async function connectToPeer(uuid, name, ip) {
487	    // 如果已有活跃连接，直接打开聊天
488	    if (activeChats.has(uuid)) {
489	        openChat(uuid);
490	        return;
491	    }
492	
493	    // 获取对端 ws_port（从在线节点列表）
494	    const peer = onlinePeers.get(uuid);
495	    if (!peer) {
496	        showToast('对方不在线');
497	        return;
498	    }
499	
500	    openChat(uuid); // 先打开聊天窗口，显示"连接中..."
501	
502	    // 连接前先刷新自己的 token（token 每3秒更新，避免用过期的）
503	    try {
504	        const resp = await fetch('/api/me');
505	        const me = await resp.json();
506	        myInfo.token = me.token;
507	    } catch (e) { /* 刷新失败则用现有 token */ }
508	
509	    try {
510	        const peerPort = peer.ws_port || 50002;
511	        const wsUrl = `ws://${peer.ip}:${peerPort}/ws/chat`;
512	        const ws = new WebSocket(wsUrl);
513	
514	        ws.onopen = () => {
515	            // 发送连接请求，带上自己的 token 给对方后端验证
516	            // 对方通过 UDP 广播收到了我的 token，验证是否匹配
517	            ws.send(JSON.stringify({
518	                type: 'connect_request',
519	                uuid: myInfo.uuid,
520	                name: myInfo.name,
521	                token: myInfo.token,
522	            }));
523	        };
524	
525	        ws.onmessage = (e) => {
526	            const msg = JSON.parse(e.data);
527	            if (msg.type === 'connect_accepted') {
528	                activeChats.set(uuid, ws);
529	                setupPeerMessageHandler(uuid, ws);
530	                addSystemMessage(uuid, '连接已建立');
531	                // 通知自己后端保存联系人（对方后端已保存，自己后端也需要记录）
532	                controlWs.send(JSON.stringify({
533	                    type: 'save_contact',
534	                    uuid: uuid,
535	                    name: name,
536	                    ip: ip,
537	                }));
538	            } else if (msg.type === 'connect_rejected') {
539	                ws.close();
540	                const reason = msg.reason === 'invalid_token' ? 'Token 验证失败，请稍后重试' : '对方拒绝了连接请求';
541	                addSystemMessage(uuid, reason);
542	                showToast(reason);
543	            }
544	        };
545	
546	        ws.onclose = () => {
547	            activeChats.delete(uuid);
548	            if (currentChat === uuid) {
549	                addSystemMessage(uuid, '连接已断开');
550	                updateChatHeaderStatus();
551	            }
552	        };
553	
554	        ws.onerror = () => {
555	            activeChats.delete(uuid);
556	            addSystemMessage(uuid, '连接失败，请检查网络');
557	            showToast('连接失败');
558	            ws.close();
559	        };
560	
561	    } catch (e) {
562	        addSystemMessage(uuid, `连接失败: ${e.message}`);
563	    }
564	}
565	
566	/** 为对端 WS 设置消息处理器（收到 connect_accepted 后调用） */
567	function setupPeerMessageHandler(uuid, ws) {
568	    ws.onmessage = (e) => {
569	        const msg = JSON.parse(e.data);
570	        if (msg.type === 'chat') {
571	            // 对方发来的聊天消息（直接从 ws 收到时也需要处理）
572	            handleDirectChatMessage(uuid, msg);
573	        } else if (msg.type === 'file_response') {
574	            handleFileRequestResponse(msg);
575	        } else if (msg.type === 'file_cancel') {
576	            handleTransferCancelled(msg);
577	        } else if (msg.type === 'ack') {
578	            handleMessageAck(msg);
579	        }
580	    };
581	}
582	
583	function handleDirectChatMessage(uuid, msg) {
584	    if (!contacts.has(uuid)) {
585	        contacts.set(uuid, { name: msg.from_name, ip: '', status: 'online', messages: [] });
586	    }
587	    contacts.get(uuid).messages.push({
588	        from: uuid,
589	        content: msg.content,
590	        msg_id: msg.msg_id,
