660	    if (!contact.messages) contact.messages = [];
661	    contact.messages.push({
662	        from: 'me',
663	        content: content,
664	        msg_id: msgId,
665	        timestamp: new Date().toISOString(),
666	        status: 'sending',
667	    });
668	    renderMessages(currentChat);
669	
670	    pendingMessages.set(msgId, { content, uuid: currentChat, status: 'sending' });
671	
672	    // 判断发送路径：
673	    //   - 主动发起方：有 chat WS（直接连对方后端 /ws/chat），通过它发送
674	    //   - 被动接收方：没有 chat WS，通过 control WS 发给自己后端，
675	    //                 自己后端复用发起方建立的 chat WS 回传给对方
676	    const chatWs = activeChats.get(currentChat);
677	    if (chatWs && chatWs.readyState === WebSocket.OPEN) {
678	        chatWs.send(JSON.stringify({
679	            type: 'chat',
680	            msg_id: msgId,
681	            content: content,
682	        }));
683	        // chat WS 直连绕过自己后端，需额外通知自己后端保存消息
684	        controlWs.send(JSON.stringify({
685	            type: 'save_message',
686	            peer_uuid: currentChat,
687	            sender: 'me',
688	            content: content,
689	            msg_id: msgId,
690	        }));
691	    } else {
692	        controlWs.send(JSON.stringify({
693	            type: 'chat_message',
694	            to_uuid: currentChat,
695	            msg_id: msgId,
696	            content: content,
697	        }));
698	    }
699	
700	    // 5秒超时：没收到 ACK 则标记失败
701	    setTimeout(() => {
702	        const pending = pendingMessages.get(msgId);
703	        if (pending && pending.status === 'sending') {
704	            pending.status = 'failed';
705	            pendingMessages.set(msgId, pending);
706	            if (currentChat) renderMessages(currentChat);
707	        }
708	    }, 5000);
