755	async function sendFile(uuid, file) {
756	    const CHUNK_SIZE = 64 * 1024; // 64KB
757	    const transferId = 't_' + myInfo.uuid + '_' + Date.now();
758	    const totalChunks = Math.ceil(file.size / CHUNK_SIZE);
759	
760	    // 通过聊天 WS 发 file_request
761	    const ws = activeChats.get(uuid);
762	    if (!ws) {
763	        showToast('未连接到对方，请先建立聊天');
764	        return;
765	    }
766	
767	    ws.send(JSON.stringify({
768	        type: 'file_request',
769	        transfer_id: transferId,
770	        file_name: file.name,
771	        file_size: file.size,
772	        chunk_size: CHUNK_SIZE,
773	        total_chunks: totalChunks,
774	        resume: false,
775	    }));
776	
777	    // 等待 file_response（通过 control ws 回调继续）
778	    addSystemMessage(uuid, `发送文件: ${file.name} (${formatSize(file.size)})`);
779	
780	    // 开始发送分片
781	    window._pendingFileTransfers = window._pendingFileTransfers || {};
782	    window._pendingFileTransfers[transferId] = { file, uuid, totalChunks, CHUNK_SIZE, transferId, currentChunk: 0 };
783	
784	    // 等待对方响应后开始发送分片
785	    const originalHandler = handleFileRequestResponse;
786	    const onceHandler = (msg) => {
787	        if (msg.transfer_id === transferId) {
788	            if (msg.accepted) {
789	                startChunkUpload(transferId);
790	            }
791	            // 恢复原始处理器
792	            window._fileResponseHandler = originalHandler;
793	        }
794	    };
795	    window._fileResponseHandler = (msg) => {
796	        originalHandler(msg);
797	        onceHandler(msg);
798	    };
799	}
800	
801	function handleFileRequestResponse(msg) {
802	    if (window._fileResponseHandler) {
803	        window._fileResponseHandler(msg);
804	    } else if (msg.accepted) {
805	        // 查找匹配的传输并开始上传
806	        const transfers = window._pendingFileTransfers || {};
807	        for (const [tid, t] of Object.entries(transfers)) {
808	            if (!t.started) {
809	                t.started = true;
810	                startChunkUpload(tid);
811	                break;
812	            }
813	        }
814	    }
815	}
816	
817	async function startChunkUpload(transferId) {
818	    const t = window._pendingFileTransfers?.[transferId];
819	    if (!t) return;
820	
821	    const peer = onlinePeers.get(t.uuid);
822	    if (!peer) {
823	        showToast('对方不在线，无法发送文件');
824	        return;
825	    }
826	
827	    const file = t.file;
828	    const CHUNK_SIZE = t.CHUNK_SIZE;
829	    const totalChunks = t.totalChunks;
830	
831	    for (let i = t.currentChunk; i < totalChunks; i++) {
832	        const start = i * CHUNK_SIZE;
833	        const end = Math.min(start + CHUNK_SIZE, file.size);
834	        const blob = file.slice(start, end);
835	        const dataB64 = await readAsBase64(blob);
836	
837	        let retries = 0;
838	        let success = false;
839	
840	        while (retries < 3 && !success) {
841	            try {
842	                const peerPort = peer.ws_port || 50002;
843	            const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/chunk`, {
844	                    method: 'POST',
845	                    headers: { 'Content-Type': 'application/json' },
846	                    body: JSON.stringify({
847	                        transfer_id: transferId,
848	                        chunk_index: i,
849	                        data: dataB64,
850	                    }),
851	                });
852	                if (resp.ok) {
853	                    success = true;
854	                    t.currentChunk = i + 1;
855	                } else {
856	                    retries++;
857	                }
858	            } catch (e) {
859	                retries++;
860	            }
861	        }
862	
863	        if (!success) {
864	            addSystemMessage(t.uuid, '文件传输中断，等待对方重新上线');
865	            return; // 传输暂停，等待后续续传
866	        }
867	    }
868	
869	    // 完成
870	    try {
871	        const peerPort = peer.ws_port || 50002;
872	        await fetch(`http://${peer.ip}:${peerPort}/api/transfer/complete`, {
873	            method: 'POST',
874	            headers: { 'Content-Type': 'application/json' },
875	            body: JSON.stringify({ transfer_id: transferId }),
876	        });
877	        addSystemMessage(t.uuid, `文件 ${file.name} 发送完成 ✓`);
878	    } catch (e) {
879	        addSystemMessage(t.uuid, '文件传输完成确认失败');
880	    }
881	
882	    delete window._pendingFileTransfers?.[transferId];
883	}
884	
885	function readAsBase64(blob) {
886	    return new Promise((resolve) => {
887	        const reader = new FileReader();
888	        reader.onloadend = () => {
889	            const result = reader.result;
890	            // 去掉 "data:...;base64," 前缀
891	            const b64 = result.split(',')[1] || result;
892	            resolve(b64);
893	        };
894	        reader.readAsDataURL(blob);
895	    });
896	}
